import com.vaadin.flow.component.applayout.AppLayout;
import com.vaadin.flow.component.applayout.DrawerToggle;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.html.UnorderedList;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.Route;

@Route
public class MainView extends AppLayout {
    private UnorderedList itemsList = new UnorderedList();
    private Span itemCount = new Span("Items: 0");
    private TextField itemField = new TextField("Item");
    private int count = 0;

    public MainView() {
        // Set up the navbar with the H2 title
        H2 title = new H2("Item Tracker");
        addToNavbar(title);

        // Set up the content area
        VerticalLayout content = new VerticalLayout();
        content.setPadding(true);

        H1 heading = new H1("Items");
        content.add(heading);

        itemField.setVisible(true);
        itemField.setValue("");
        content.add(itemField);

        Button addButton = new Button("Add", event -> handleAdd());
        Button clearButton = new Button("Clear", event -> handleClear());
        content.add(addButton, clearButton);

        content.add(itemsList);
        content.add(itemCount);

        setContent(content);
    }

    private void handleAdd() {
        String value = itemField.getValue();
        if (value == null || value.trim().isEmpty()) {
            itemField.setInvalid(true);
        } else {
            itemField.setInvalid(false);
            ListItem item = new ListItem(value);
            itemsList.add(item);
            itemField.setValue("");
            count++;
            updateCount();
        }
    }

    private void handleClear() {
        itemsList.removeAll();
        count = 0;
        updateCount();
    }

    private void updateCount() {
        itemCount.setText("Items: " + count);
    }
